import api from './api';

// chat service could include HTTP helpers e.g. createChannel, fetchMessages
export const chatService = {
  fetchChannels: () => api.get('/chat/channels').then(res => res.data),
  fetchMessages: (channelId) => api.get(`/chat/channels/${channelId}/messages`).then(res => res.data),
};
